const cfg = $('Configuration').first().json;
const items = $input.all();
const redactValues = String(cfg.redactSecretValues) !== 'false';

const RULES = [
  { id: 'private_key', sev: 'critical', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g },
  { id: 'aws_key', sev: 'critical', re: /\bAKIA[0-9A-Z]{16}/g },
  { id: 'jwt', sev: 'critical', re: /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g },
  { id: 'bearer_token', sev: 'critical', re: /\bBearer\s+[A-Za-z0-9._~+\/-]{20,}/gi },
  { id: 'slack_token', sev: 'critical', re: /\bxox[abprs]-[A-Za-z0-9-]{10,}/g },
  { id: 'github_pat', sev: 'critical', re: /\bgh[pousr]_[A-Za-z0-9]{30,}/g },
  { id: 'openai_key', sev: 'critical', re: /\bsk-[A-Za-z0-9_-]{20,}/g },
  { id: 'url_secret_param', sev: 'high', re: /([?&](?:key|token|api_?key|access_?token|auth|password|secret)=)([A-Za-z0-9._~+\/=-]{8,})/gi },
  { id: 'email_address', sev: 'medium', re: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g }
];

const RANK = { critical: 4, high: 3, medium: 2, low: 1, none: 0 };
const out = [];

for (const item of items) {
  const wf = JSON.parse(JSON.stringify(item.json));
  const findings = [];
  const add = (id, severity, location, occurrences) => findings.push({ id, severity, location, occurrences });

  if (wf.meta && wf.meta.instanceId) { delete wf.meta.instanceId; add('instance_id', 'low', 'meta.instanceId', 1); }

  if (wf.pinData && Object.keys(wf.pinData).length > 0) {
    const pinnedCount = Object.keys(wf.pinData).length;
    wf.pinData = {};
    add('pinned_data', 'medium', 'pinData', pinnedCount);
  }

  let hookCount = 0;
  let credCount = 0;
  const nodeList = wf.nodes || [];
  for (const nd of nodeList) {
    if (nd.webhookId) { delete nd.webhookId; hookCount++; }
    if (nd.credentials) {
      for (const key of Object.keys(nd.credentials)) {
        if (nd.credentials[key] && nd.credentials[key].id) { nd.credentials[key].id = ''; credCount++; }
      }
    }
  }
  if (hookCount > 0) add('webhook_id', 'low', 'nodes[].webhookId', hookCount);
  if (credCount > 0) add('credential_id', 'medium', 'nodes[].credentials', credCount);

  let text = JSON.stringify(wf, null, 2);
  for (const rule of RULES) {
    const hits = text.match(rule.re);
    if (hits && hits.length > 0) {
      add(rule.id, rule.sev, 'node parameters', hits.length);
      if (redactValues) {
        if (rule.id === 'url_secret_param') {
          text = text.replace(rule.re, '$1[REDACTED]');
        } else {
          text = text.replace(rule.re, '[REDACTED_' + rule.id.toUpperCase() + ']');
        }
      }
    }
  }

  let top = 'none';
  for (const f of findings) { if (RANK[f.severity] > RANK[top]) top = f.severity; }

  const slug = String(wf.name || 'unnamed').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);

  out.push({ json: {
    workflowId: String(wf.id || 'unknown'),
    workflowName: wf.name || 'unnamed',
    filePath: String(cfg.repoPath || 'workflows/') + String(wf.id || 'unknown') + '-' + slug + '.json',
    redactedJson: text,
    findings: findings,
    findingCount: findings.length,
    highestSeverity: top
  }});
}

return out;

const cfg = $('Configuration').first().json;
const scans = $('Scan and Redact').all().map(i => i.json);

const RANK = { critical: 4, high: 3, medium: 2, low: 1, none: 0 };
const gate = String(cfg.alertSeverityThreshold || 'medium').toLowerCase();
const gateRank = RANK[gate] || 2;

let totalFindings = 0;
const bySeverity = { critical: 0, high: 0, medium: 0, low: 0 };
const offenders = [];

for (const s of scans) {
  totalFindings += s.findingCount || 0;
  const fl = s.findings || [];
  for (const f of fl) {
    if (bySeverity[f.severity] !== undefined) bySeverity[f.severity] += (f.occurrences || 1);
  }
  if ((s.findingCount || 0) > 0 && (RANK[s.highestSeverity] || 0) >= gateRank) offenders.push(s);
}

offenders.sort((a, b) => ((RANK[b.highestSeverity] || 0) - (RANK[a.highestSeverity] || 0)) || (b.findingCount - a.findingCount));

const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lines = [];
lines.push('<b>n8n secret audit</b>');
lines.push('Scanned ' + scans.length + ' workflows, ' + totalFindings + ' findings total');
lines.push('critical ' + bySeverity.critical + ' / high ' + bySeverity.high + ' / medium ' + bySeverity.medium + ' / low ' + bySeverity.low);

if (offenders.length === 0) {
  lines.push('');
  lines.push('Nothing at or above ' + gate + ' severity.');
} else {
  lines.push('');
  lines.push('<b>At or above ' + gate + '</b>');
  const shown = offenders.slice(0, 15);
  for (const o of shown) {
    const kinds = (o.findings || []).map(f => f.id).filter((v, i, a) => a.indexOf(v) === i).join(', ');
    lines.push('');
    lines.push('<b>' + esc(o.workflowName) + '</b> [' + o.highestSeverity + ']');
    lines.push('<code>' + esc(o.workflowId) + '</code> ' + o.findingCount + ' findings');
    lines.push(esc(kinds));
  }
  if (offenders.length > shown.length) {
    lines.push('');
    lines.push('and ' + (offenders.length - shown.length) + ' more workflows');
  }
}

let reportText = lines.join('\n');
if (reportText.length > 3800) reportText = reportText.slice(0, 3800) + '\n...truncated';

return [{ json: {
  reportText: reportText,
  totalWorkflows: scans.length,
  totalFindings: totalFindings,
  alertCount: offenders.length,
  bySeverity: bySeverity
} }];
